const original = $('Filtrar Cidade e Situacao Ativa').item.json;
const api = $json;

return { json: {
  ...original,
  razao_social: api.razao_social || api.nome_fantasia || '',
  cnae_descricao: api.cnae_fiscal_descricao || '',
  porte: api.porte || '',
  situacao_cadastral: api.descricao_situacao_cadastral || '',
  capital_social: Number(api.capital_social) || 0,
  socios: Array.isArray(api.qsa) ? api.qsa.map(s => s.nome_socio).filter(Boolean).join('; ') : (original.socios || ''),
  fonte_enriquecimento: 'BrasilAPI'
} };

const original = $('Filtrar Cidade e Situacao Ativa').item.json;
const api = $json;
const capitalSocialNum = Number((api.capital_social || '0').toString().replace(/\./g, '').replace(',', '.')) || 0;

return { json: {
  ...original,
  razao_social: api.razao_social || api.nome_fantasia || '',
  cnae_descricao: api.cnae_principal || '',
  porte: api.porte_empresa || '',
  situacao_cadastral: api.situacao_cadastral || '',
  capital_social: capitalSocialNum,
  socios: original.socios || '',
  fonte_enriquecimento: 'OpenCNPJ'
} };

const item = $json;

// --- Constantes ajustáveis — recalibrar depois de ver dados reais do segmento buscado ---
const CAPITAL_SOCIAL_QUENTE = 100000;
const CAPITAL_SOCIAL_ATENCAO = 20000;

function normalizarPorte(raw) {
  const v = (raw ?? '').toString().trim().toUpperCase();
  if (['01', '1', 'MICRO EMPRESA', 'ME'].includes(v)) return 'ME';
  if (['03', '3', 'EMPRESA DE PEQUENO PORTE', 'EPP'].includes(v)) return 'EPP';
  if (['05', '5', 'DEMAIS', 'DEMAIS EMPRESAS'].includes(v)) return 'DEMAIS';
  return 'DESCONHECIDO';
}

const porte = normalizarPorte(item.porte);
const capitalSocial = Number(item.capital_social) || 0;

let tier = 'desqualificado';
if (porte === 'DEMAIS' && capitalSocial >= CAPITAL_SOCIAL_QUENTE) tier = 'quente';
else if (porte === 'DEMAIS' || (porte === 'EPP' && capitalSocial >= CAPITAL_SOCIAL_ATENCAO)) tier = 'atencao';

// Valores INTERNOS da propriedade lifecyclestage (Lifecycle Stage), que é a
// propriedade usada pelo Board de Contatos nesta conta do HubSpot — NÃO é
// hs_lead_status (confirmado via GET /crm/v3/properties/contacts/lifecyclestage).
// 'lead' e 'opportunity' são valores padrão do HubSpot; '1398914058' é o valor
// interno auto-gerado quando a opção customizada "Nutrir" foi criada nesta
// conta — não é literalmente a string 'nutrir'. Se recriar a opção em outra
// conta, confira o valor de novo em Configurações > Propriedades > Lifecycle Stage.
const HUBSPOT_LIFECYCLE_STAGE = {
  quente: 'lead',
  atencao: 'opportunity',
  desqualificado: '1398914058'
};

return { json: {
  ...item,
  porte,
  tier,
  lifecyclestage: HUBSPOT_LIFECYCLE_STAGE[tier],
  timestamp: new Date().toISOString()
} };

const item = $json;

const systemPrompt = 'Você é um SDR da ALPHADATA, uma plataforma de inteligência de mercado B2B. Dado os dados de uma empresa encontrada numa busca de prospecção por segmento/estado/cidade, responda SOMENTE em JSON válido com duas chaves: resumo_ia (resumo de 1 a 2 frases sobre a empresa e a oportunidade) e abordagem_sugerida (1 frase com o melhor ângulo de abordagem comercial). Não inclua nenhum texto fora do JSON.';

const userPrompt = [
  `Empresa: ${item.razao_social}`,
  `CNAE: ${item.cnae_descricao}`,
  `Situação cadastral: ${item.situacao_cadastral}`,
  `Porte: ${item.porte}`,
  `Capital social: R$ ${item.capital_social}`,
  `Localização: ${item.municipio}/${item.uf}`,
  `Tier calculado: ${item.tier}`
].join('\n');

return { json: {
  ...item,
  openai_request_body: JSON.stringify({
    model: 'gpt-4o-mini',
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ]
  })
} };

const original = $('Montar Prompt IA').item.json;
let resumo_ia = '';
let abordagem_sugerida = '';

try {
  const content = $json?.choices?.[0]?.message?.content || '{}';
  const result = JSON.parse(content);
  resumo_ia = result.resumo_ia || '';
  abordagem_sugerida = result.abordagem_sugerida || '';
} catch (e) {
  // mantém strings vazias se a IA falhar ou responder fora do formato esperado
}

const { openai_request_body, ...rest } = original;

return { json: {
  ...rest,
  resumo_ia,
  abordagem_sugerida
} };

const item = $json;
const resumo = `🔥 EMPRESA QUENTE — vale abordar!

Empresa: ${item.razao_social}
CNPJ: ${item.cnpj}
Segmento (CNAE): ${item.cnae_descricao}
Situação cadastral: ${item.situacao_cadastral}
Porte: ${item.porte} | Capital social: R$ ${item.capital_social}
Localização: ${item.municipio}/${item.uf}

📊 Análise da IA: ${item.resumo_ia || 'não disponível'}
💡 Abordagem sugerida: ${item.abordagem_sugerida || 'não disponível'}

Contato: ${item.email || 'email não informado'} | ${item.ddd_telefone_1 || 'telefone não informado'}
Sócios: ${item.socios || 'não informado'}
Fonte do enriquecimento: ${item.fonte_enriquecimento}`;

return { json: { ...item, resumo } };

const item = $json;
const resumo = `🟡 Empresa em atenção — vale acompanhar.

Empresa: ${item.razao_social}
CNPJ: ${item.cnpj}
Segmento (CNAE): ${item.cnae_descricao}
Situação cadastral: ${item.situacao_cadastral}
Porte: ${item.porte} | Capital social: R$ ${item.capital_social}
Localização: ${item.municipio}/${item.uf}

📊 Análise da IA: ${item.resumo_ia || 'não disponível'}
💡 Abordagem sugerida: ${item.abordagem_sugerida || 'não disponível'}

Contato: ${item.email || 'email não informado'} | ${item.ddd_telefone_1 || 'telefone não informado'}
Sócios: ${item.socios || 'não informado'}
Fonte do enriquecimento: ${item.fonte_enriquecimento}`;

return { json: { ...item, resumo } };

const leads = items.map(i => i.json).filter(l => l && Object.keys(l).length > 0);

const total = leads.length;
const countQuente = leads.filter(l => l.tier === 'quente').length;
const countAtencao = leads.filter(l => l.tier === 'atencao').length;
const countDesqualificado = leads.filter(l => l.tier === 'desqualificado').length;

let maiorTicket = null;
let menorTicket = null;

for (const lead of leads) {
  const ticket = Number(lead.ticket_medio_mensal) || 0;
  if (!maiorTicket || ticket > (Number(maiorTicket.ticket_medio_mensal) || 0)) {
    maiorTicket = lead;
  }
  if (!menorTicket || ticket < (Number(menorTicket.ticket_medio_mensal) || 0)) {
    menorTicket = lead;
  }
}

return [{
  json: { total, countQuente, countAtencao, countDesqualificado, maiorTicket, menorTicket }
}];

const item = items[0].json;
const total = item.total;
const maiorTicket = item.maiorTicket;
const menorTicket = item.menorTicket;

const fmtMoeda = (v) => 'R$ ' + Number(v || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

function blocoLead(lead, titulo) {
  if (!lead) return `<p>${titulo}: nenhum lead disponível.</p>`;
  const cnae = lead.cnae_descricao || lead.cnae_decricao || '-';
  return `
    <div style="border:1px solid #ddd;border-radius:8px;padding:12px;margin:8px 0;">
      <h3 style="margin:0 0 8px 0;">${titulo}</h3>
      <p><strong>Nome:</strong> ${lead.nome || '-'}</p>
      <p><strong>Empresa:</strong> ${lead.razao_social || lead.empresa || '-'}</p>
      <p><strong>Ticket médio mensal:</strong> ${fmtMoeda(lead.ticket_medio_mensal)}</p>
      <p><strong>Porte:</strong> ${lead.porte || '-'}</p>
      <p><strong>Segmento (CNAE):</strong> ${cnae}</p>
      <p><strong>Resumo da IA:</strong> ${lead.resumo_ia || 'não disponível'}</p>
    </div>`;
}

const html = total === 0
  ? `<h2>📊 Relatório diário de leads — CadastroLeads</h2><p>Nenhum lead cadastrado na planilha ainda.</p>`
  : `
    <h2>📊 Relatório diário de leads — CadastroLeads</h2>
    <p>Total de leads cadastrados (acumulado, todas as linhas da planilha): <strong>${total}</strong></p>
    <ul>
      <li>🔥 Quente: <strong>${item.countQuente}</strong></li>
      <li>🟡 Atenção: <strong>${item.countAtencao}</strong></li>
      <li>🌱 Nutrir (desqualificado): <strong>${item.countDesqualificado}</strong></li>
    </ul>
    ${blocoLead(maiorTicket, '💰 Maior ticket médio mensal')}
    ${blocoLead(menorTicket, '📉 Menor ticket médio mensal')}
  `;

const subject = `Relatório diário de leads — ${total} leads (${new Date().toLocaleDateString('pt-BR')})`;

return [{ json: { subject, htmlBody: html } }];

const SEGMENTO_CNAE_MAP = {
  tecnologia: ['6201501'], varejo_vestuario: ['4781400'], alimentacao: ['5611201'],
  construcao_civil: ['4120400'], saude_odonto: ['8630504'], educacao_idiomas: ['8593700'],
  beleza_estetica: ['9602501'], contabilidade_consultoria: ['6920601'],
  logistica_transporte: ['4930202'], ecommerce: ['4791100'],
  seguranca_patrimonial: ['8011101'], limpeza_zeladoria: ['8121400'], mecanica: ['4520001'],
  advocacia: ['6911701'], imobiliarias: ['6821801'], academias_fitness: ['9313100'],
  hotelaria: ['5510801'], farmacias: ['4771701'], petshop_veterinaria: ['7500100'],
  publicidade_marketing: ['7311400'], recursos_humanos: ['7810800'],
  transporte_passageiros: ['4922101'], graficas: ['1811301'], moveis_decoracao: ['4754701'],
  seguros: ['6622300'], clinicas_medicas: ['8630503'], fisioterapia: ['8650002'],
  padaria: ['4721101'], agencia_viagens: ['7911200'], escolas: ['8513900'],
  material_construcao: ['4744099'], papelaria: ['4761003'], bares: ['5611202']
};
const item = items[0].json;
const cnaes = SEGMENTO_CNAE_MAP[item.segmento] || [];
return cnaes.map(cnae => ({ json: { ...item, cnae } }));

const search = $('Normalizar Busca').first().json;
const companies = [];
for (const response of items) {
  const data = Array.isArray(response.json.data) ? response.json.data : [];
  for (const company of data) {
    companies.push({ json: { ...company, segmento: search.segmento, uf: search.estado, cidade: search.cidade, telefone_sdr: search.telefone_sdr } });
  }
}
return companies;

const MAX_RESULTADOS = 100;
const normalizar = s => (s || '').toString().trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const soDigitos = s => (s || '').toString().replace(/\D/g, '');
const alvo = normalizar(items[0]?.json.cidade);
const cnpjsExistentes = new Set($('Buscar CNPJs Existentes').all().map(i => soDigitos(i.json.cnpj)));
const filtrados = items.filter(i => {
  const municipio = normalizar(i.json.municipio);
  const situacao = (i.json.descricao_situacao_cadastral || '').toString().trim().toUpperCase();
  const jaExiste = cnpjsExistentes.has(soDigitos(i.json.cnpj));
  const cidadeOk = !alvo || municipio === alvo;
  return cidadeOk && situacao === 'ATIVA' && !jaExiste;
});
return filtrados.slice(0, MAX_RESULTADOS);

const api = $json;
return { json: {
  ...api,
  razao_social: api.razao_social || api.nome_fantasia || '',
  cnae_descricao: api.cnae_fiscal_descricao || '',
  porte: api.porte || '',
  situacao_cadastral: api.descricao_situacao_cadastral || '',
  capital_social: Number(api.capital_social) || 0,
  socios: Array.isArray(api.qsa) ? api.qsa.map(s => s.nome_socio).filter(Boolean).join('; ') : '',
  fonte_enriquecimento: 'MinhaReceita'
} };

const search = $('Normalizar Busca').first().json;
const companies = items.map(i => {
  const c = i.json;
  return {
    cnpj: c.cnpj,
    razao_social: c.razao_social,
    cnae_descricao: c.cnae_descricao,
    situacao_cadastral: c.situacao_cadastral,
    porte: c.porte,
    capital_social: c.capital_social,
    municipio: c.municipio,
    uf: c.uf,
    email: c.email || '',
    telefone: c.ddd_telefone_1 || '',
    socios: c.socios || '',
    tier: c.tier,
    resumo_ia: c.resumo_ia || '',
    abordagem_sugerida: c.abordagem_sugerida || '',
    fonte_enriquecimento: c.fonte_enriquecimento
  };
});

return [{ json: {
  status: 'ok',
  segmento: search.segmento,
  estado: search.estado,
  cidade: search.cidade,
  total_encontrado: companies.length,
  companies
} }];

const item = $json;

function soDigitos(v) { return (v || '').toString().replace(/\D/g, ''); }

function formatarTelefone(raw) {
  let r = soDigitos(raw);
  if ((r.length === 12 || r.length === 13) && r.startsWith('55')) r = r.slice(2);
  if (r.length < 10) return r;
  const ddd = r.slice(0, 2);
  const rest = r.slice(2);
  const mid = rest.length === 9 ? rest.slice(0, 5) : rest.slice(0, 4);
  const end = rest.length === 9 ? rest.slice(5) : rest.slice(4);
  return `(${ddd}) ${mid}-${end}`;
}

function formatarCnpj(raw) {
  const c = soDigitos(raw);
  return c.length === 14 ? `${c.slice(0,2)}.${c.slice(2,5)}.${c.slice(5,8)}/${c.slice(8,12)}-${c.slice(12,14)}` : (raw || '');
}

function formatarCep(raw) {
  const c = soDigitos(raw);
  return c.length === 8 ? `${c.slice(0,5)}-${c.slice(5)}` : (raw || '');
}

function formatarCnaeFiscal(raw) {
  const c = soDigitos(raw);
  return c.length === 7 ? `${c.slice(0,4)}-${c.slice(4,5)}/${c.slice(5)}` : (raw || '');
}

function formatarCnaesSecundarios(arr) {
  if (!Array.isArray(arr) || arr.length === 0) return '';
  return arr.map(c => `${c.codigo || ''} - ${c.descricao || ''}`).join('; ');
}

return { json: {
  timestamp: item.timestamp,
  cnpj: formatarCnpj(item.cnpj),
  razao_social: item.razao_social || '',
  porte: item.porte || '',
  situacao_cadastral: item.situacao_cadastral || '',
  capital_social: 'R$ ' + Number(item.capital_social || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }),
  tier: item.tier || '',
  telefone_sdr: formatarTelefone(item.telefone_sdr),
  cnae_descricao: item.cnae_descricao || '',
  fonte_enriquecimento: item.fonte_enriquecimento || '',
  uf: item.uf || '',
  cep: formatarCep(item.cep),
  pais: item.pais || '',
  bairro: item.bairro || '',
  numero: (item.numero || '').toString(),
  municipio: item.municipio || '',
  logradouro: item.logradouro || '',
  cnae_fiscal: formatarCnaeFiscal(item.cnae_fiscal),
  complemento: item.complemento || '',
  codigo_porte: (item.codigo_porte ?? '').toString(),
  nome_fantasia: item.nome_fantasia || '',
  ddd_telefone_1: formatarTelefone(item.ddd_telefone_1),
  ddd_telefone_2: formatarTelefone(item.ddd_telefone_2),
  opcao_pelo_mei: item.opcao_pelo_mei ? 'Sim' : 'Não',
  cnaes_secundarios: formatarCnaesSecundarios(item.cnaes_secundarios),
  natureza_juridica: item.natureza_juridica || '',
  cnae_fiscal_descricao: item.cnae_fiscal_descricao || '',
  descricao_identificador_matriz_filial: item.descricao_identificador_matriz_filial || '',
  segmento: item.segmento || '',
  cidade: item.cidade || '',
  socios: item.socios || '',
  email: item.email || '',
} };
